@test
def test_proj_io():
    p = mne.read_proj(D + "tl_proj.fif")
    assert len(p) == 2
    assert p[0]["desc"] == "p1"
    assert not p[0]["active"]
    assert p[1]["active"]
    close("p1", p[0]["data"]["data"], [0.6000000238418579, 0.800000011920929])
    close("p2", p[1]["data"]["data"], [0.5, 0.5, 0.7071067690849304, 0.7071067690849304, -0.7071067690849304, 0.0])
