@test
def test_stc_io():
    s = mne.read_source_estimate(D + "tl_stc")
    close("stc", s.data, [0.0, 0.10000000149011612, 0.20000000298023224, 0.30000001192092896, 0.4000000059604645, 0.5, 0.6000000238418579, 0.699999988079071, 0.800000011920929, 0.8999999761581421, 1.0, 1.100000023841858, 1.2000000476837158, 1.2999999523162842, 1.399999976158142, 1.5, 1.600000023841858, 1.7000000476837158, 1.7999999523162842, 1.899999976158142], 1e-6)
    close("tmin", [s.tmin, s.tstep], [0.01, 0.02], 1e-6)
    assert s.vertices[0].tolist() == [0, 2, 5]
    assert s.vertices[1].tolist() == [1, 4]
    w = mne.read_source_estimate(D + "tl_w")
    close("w", w.data, [0.0, 0.30000001192092896, 0.6000000238418579, 0.8999999761581421, 1.2000000476837158], 1e-6)
    vs = mne.VectorSourceEstimate(np.ones((5, 3, 2)), [np.array([0, 2, 5]), np.array([1, 4])], 0.0, 0.1)
    assert vs.data.shape == (5, 3, 2)
test_stc_io()


@test
def test_labels_io():
    l = mne.read_label(D + "tl_L1-lh.label")
    assert l.vertices.tolist() == [3, 5, 9]
    close("pos", l.pos, [0.001, 0.002, 0.003, 0.004, 0.005, 0.006, 0.007, 0.008, 0.009000000000000001])
    close("values", l.values, [0.5, 1.0, 0.25])
    assert l.name == 'tl_L1-lh'
    assert l.hemi == "lh"
    mne.write_label("/tmp/typhon_tl_L1-lh.label", l)
    l2 = mne.read_label("/tmp/typhon_tl_L1-lh.label")
    close("pos2", l2.pos, [0.001, 0.002, 0.003, 0.004, 0.005, 0.006, 0.007, 0.008, 0.009000000000000001])
test_labels_io()


@test
def test_surface_tri():
    rr, tris = mne.read_tri(D + "tl.tri")
    close("rr", rr, [0.44122748688504143, -0.33087015189408764, 2.43077118700778, -0.2520921296030769, 0.10960984157818278, 1.5824811170615634, -0.9092324048562419, -0.5916366579302884, 0.18760322583703548, -0.32986995777935924, -1.192764612421806, -0.2048765105875873, -0.3588289470012431, 0.6034716026094954, -1.6647885294716944, -0.7001790376899514, 1.1513910094871702, 1.8573310072313118])
    assert tris.tolist() == [[0, 1, 2], [2, 1, 3], [3, 4, 2], [4, 5, 2]]
    rr2, tris2 = mne.read_surface(D + "tl.obj")
    close("rr2", rr2, [0.44122748688504143, -0.33087015189408764, 2.43077118700778, -0.2520921296030769, 0.10960984157818278, 1.5824811170615634, -0.9092324048562419, -0.5916366579302884, 0.18760322583703548, -0.32986995777935924, -1.192764612421806, -0.2048765105875873, -0.3588289470012431, 0.6034716026094954, -1.6647885294716944, -0.7001790376899514, 1.1513910094871702, 1.8573310072313118])
    assert tris2.tolist() == [[0, 1, 2], [2, 1, 3], [3, 4, 2], [4, 5, 2]]
test_surface_tri()


@test
def test_config_misc():
    mne.set_config("MNE_LOGGING_LEVEL", "WARNING", home_dir="/tmp/typhon_tl_home", set_env=False)
    assert mne.get_config("MNE_LOGGING_LEVEL", home_dir="/tmp/typhon_tl_home", use_env=False) == "WARNING"
    assert mne.get_config_path("/tmp/typhon_tl_home") == "/tmp/typhon_tl_home/.mne/mne-python.json"
    sel = mne.read_vectorview_selection("Left-temporal")
    assert len(sel) == 39
    assert sel[0] == 'MEG 0111'
    assert sel[-1] == 'MEG 1623'
    sel2 = mne.read_vectorview_selection(["Vertex", "Right-occipital"])
    assert len(sel2) == 71
    ids, cols = mne.read_freesurfer_lut()
    assert ids["Left-Hippocampus"] == 17
    close("lutcol", cols["Left-Hippocampus"], [220.0, 216.0, 20.0, 0.0])
    rj = mne.read_reject_parameters(D + "tl.cov")
    close("rej", [rj["grad"], rj["mag"], rj["eeg"], rj["eog"]], [4e-10, 4e-12, 4e-05, 0.00025])
    v = mne.grade_to_vertices("fsaverage", 5)
    assert v[0].shape[0] == 10242
test_config_misc()
